// Return the single best-matching anchor text for a goal (plus any observed
// context), or '' when nothing clearly matches. Deliberately returns one anchor
// to keep the prompt lean; WORK_MODE already handles blending across disciplines.
export function methodAnchorFor(text) {
  const s = String(text || '')
  if (!s.trim()) return ''
  for (const a of ANCHORS) { if (a.re.test(s)) return a.text }
  return ''
}
// The discipline key only (for logging / telemetry), or null.
export function methodAnchorKey(text) {
  const s = String(text || '')
  if (!s.trim()) return null
  for (const a of ANCHORS) { if (a.re.test(s)) return a.key }
  return null
}
export const METHOD_ANCHOR_KEYS = ANCHORS.map((a) => a.key)

export default { methodAnchorFor, methodAnchorKey, METHOD_ANCHOR_KEYS }
